use std::env;

use spiral_earcut::earcut;

fn atoi_like(value: &str) -> i32 {
    let trimmed = value.trim_start_matches(|c: char| c.is_ascii_whitespace());
    let mut chars = trimmed.chars().peekable();
    let mut sign = 1i64;

    if let Some(&ch) = chars.peek() {
        if ch == '+' {
            chars.next();
        } else if ch == '-' {
            sign = -1;
            chars.next();
        }
    }

    let mut saw_digit = false;
    let mut parsed = 0i64;

    while let Some(&ch) = chars.peek() {
        if !ch.is_ascii_digit() {
            break;
        }
        saw_digit = true;
        parsed = parsed.saturating_mul(10);
        parsed = parsed.saturating_add((ch as u8 - b'0') as i64);
        chars.next();
    }

    if !saw_digit {
        0
    } else {
        let value = parsed.saturating_mul(sign);
        value.clamp(i32::MIN as i64, i32::MAX as i64) as i32
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut n = 7i32;
    if args.len() > 1 {
        n = atoi_like(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let mut spiral: Vec<[f64; 2]> = Vec::new();

    let count = n.saturating_mul(2);
    for i in 0..count {
        let t = i as f64 / count as f64;
        let radius = t;
        let angle = 4.0 * std::f64::consts::PI * t;
        spiral.push([radius * angle.cos(), radius * angle.sin()]);
    }

    polygon.push(spiral);

    let indices = earcut(&polygon);
    for idx in indices {
        print!("{idx} ");
    }
}

