use crate::geometry::{point_in_triangle, signed_area, triangle_area};
use crate::linked::{equals, insert_node, remove_node, Node};

pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let Some(outer_ring) = polygon.first() else {
        return Vec::new();
    };

    if outer_ring.len() < 3 {
        return Vec::new();
    }

    let mut nodes = Vec::with_capacity(outer_ring.len());
    let Some(mut ear) = linked_list(outer_ring, true, &mut nodes) else {
        return Vec::new();
    };

    let mut triangles = Vec::with_capacity((outer_ring.len().saturating_sub(2)) * 3);
    ear = filter_points(&mut nodes, ear);

    if nodes[ear].alive && nodes[ear].next != ear && nodes[nodes[ear].next].next != ear {
        earcut_linked(&mut nodes, ear, &mut triangles);
    }

    triangles
}

fn linked_list(points: &[[f64; 2]], clockwise: bool, nodes: &mut Vec<Node>) -> Option<usize> {
    let is_clockwise = signed_area(points) < 0.0;
    let mut last = None;

    if is_clockwise == clockwise {
        for (vertex, point) in points.iter().enumerate() {
            last = Some(insert_node(nodes, vertex, point[0], point[1], last));
        }
    } else {
        for (vertex, point) in points.iter().enumerate().rev() {
            last = Some(insert_node(nodes, vertex, point[0], point[1], last));
        }
    }

    let last_idx = last?;
    let next_idx = nodes[last_idx].next;
    if equals(nodes, last_idx, next_idx) {
        remove_node(nodes, last_idx);
        if nodes[next_idx].next == next_idx {
            return None;
        }
        return Some(next_idx);
    }

    Some(last_idx)
}

fn filter_points(nodes: &mut Vec<Node>, start: usize) -> usize {
    if nodes.is_empty() || !nodes[start].alive {
        return start;
    }

    let mut end = start;
    let mut current = start;

    loop {
        let prev = nodes[current].prev;
        let next = nodes[current].next;
        let should_remove = !nodes[current].steiner
            && (equals(nodes, current, next)
                || triangle_area(nodes[prev].point(), nodes[current].point(), nodes[next].point())
                    == 0.0);

        if should_remove {
            remove_node(nodes, current);
            current = prev;
            end = prev;
            if nodes[current].next == current {
                break;
            }
        } else {
            current = next;
        }

        if current == end {
            break;
        }
    }

    end
}

fn earcut_linked(nodes: &mut Vec<Node>, start: usize, triangles: &mut Vec<u32>) {
    let mut ear = start;
    let mut stop = start;
    let mut stalled = false;

    while nodes[ear].alive && nodes[ear].prev != nodes[ear].next {
        let prev = nodes[ear].prev;
        let next = nodes[ear].next;

        if is_ear(nodes, ear) {
            triangles.push(nodes[prev].vertex as u32);
            triangles.push(nodes[ear].vertex as u32);
            triangles.push(nodes[next].vertex as u32);

            remove_node(nodes, ear);
            ear = nodes[next].next;
            stop = ear;
            stalled = false;
            continue;
        }

        ear = next;
        if ear == stop {
            if stalled {
                break;
            }
            ear = filter_points(nodes, ear);
            stop = ear;
            stalled = true;
        }
    }
}

fn is_ear(nodes: &[Node], ear: usize) -> bool {
    let prev = nodes[ear].prev;
    let next = nodes[ear].next;

    if triangle_area(nodes[prev].point(), nodes[ear].point(), nodes[next].point()) >= 0.0 {
        return false;
    }

    let mut candidate = nodes[next].next;
    while candidate != prev {
        if point_in_triangle(
            nodes[prev].point(),
            nodes[ear].point(),
            nodes[next].point(),
            nodes[candidate].point(),
        ) && triangle_area(
            nodes[nodes[candidate].prev].point(),
            nodes[candidate].point(),
            nodes[nodes[candidate].next].point(),
        ) >= 0.0
        {
            return false;
        }
        candidate = nodes[candidate].next;
    }

    true
}

