pub fn signed_area(points: &[[f64; 2]]) -> f64 {
    let len = points.len();
    if len < 3 {
        return 0.0;
    }

    let mut area = 0.0;
    for i in 0..len {
        let j = if i == 0 { len - 1 } else { i - 1 };
        area += points[j][0] * points[i][1] - points[i][0] * points[j][1];
    }
    area * 0.5
}

pub fn triangle_area(a: [f64; 2], b: [f64; 2], c: [f64; 2]) -> f64 {
    (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
}

pub fn point_in_triangle(a: [f64; 2], b: [f64; 2], c: [f64; 2], p: [f64; 2]) -> bool {
    cross(p, a, b) >= 0.0 && cross(p, b, c) >= 0.0 && cross(p, c, a) >= 0.0
